import java.util.*;

public class KthLargestElement {

    // ====== 方法 1：快速选择（随机化 Lomuto partition） ======
    public int findKthLargestQS(int[] nums, int k) {
        int target = nums.length - k; // 第 k 大 = 升序第 (n-k) 个
        int left = 0, right = nums.length - 1;
        Random rand = new Random();
        while (left <= right) {
            // 随机选 pivot，避免已排序输入退化
            int randIdx = left + rand.nextInt(right - left + 1);
            swap(nums, randIdx, right);
            int p = partition(nums, left, right);
            if (p == target) return nums[p];
            else if (p < target) left = p + 1;
            else right = p - 1;
        }
        throw new IllegalArgumentException("unreachable");
    }

    // Lomuto partition：pivot = nums[right]，返回 pivot 最终索引
    private int partition(int[] nums, int lo, int hi) {
        int pivot = nums[hi], i = lo;
        for (int j = lo; j < hi; j++) {
            if (nums[j] <= pivot) {
                swap(nums, i, j);
                i++;
            }
        }
        swap(nums, i, hi);
        return i;
    }

    private void swap(int[] a, int i, int j) {
        int t = a[i]; a[i] = a[j]; a[j] = t;
    }

    // ====== 方法 2：小顶堆维护 k 个最大值 ======
    public int findKthLargestHeap(int[] nums, int k) {
        PriorityQueue<Integer> minHeap = new PriorityQueue<>();
        for (int num : nums) {
            minHeap.offer(num);
            if (minHeap.size() > k) minHeap.poll(); // 弹出最小，保留 k 个最大
        }
        return minHeap.peek();
    }

    // ====== 测试 ======
    public static void main(String[] args) {
        KthLargestElement s = new KthLargestElement();
        int[] nums1 = {3, 2, 1, 5, 6, 4};
        System.out.println(s.findKthLargestQS(nums1, 2));   // 5
        int[] nums2 = {3, 2, 3, 1, 2, 4, 5, 5, 6};
        System.out.println(s.findKthLargestHeap(nums2, 4)); // 4
        // 边界：k=1（最大值）, k=n（最小值）, 全相同元素
        int[] nums3 = {1};
        System.out.println(s.findKthLargestQS(nums3, 1));   // 1
        int[] nums4 = {2, 2, 2};
        System.out.println(s.findKthLargestHeap(nums4, 2)); // 2
    }
}
